// Per-token documentation comments, and the header every generated file
// carries. `docs` is one brand's Map of token path -> $description; it is
// passed explicitly so an emitter's output is a pure function of its inputs.
// Code gets the same contract Figma does — name plus description — because
// the description is where the rule that picks between two defensible tokens
// lives, and a stylesheet or a Swift file is exactly where someone (or an
// agent) makes that choice.

// emit.mjs and the drift test tell generated files from hand-written ones by
// this header, so it must never appear in a hand-written file.
export const GENERATED = 'Generated by projects/ignite/theme/scripts from tokens/** — do not edit by hand.';

// One line per part: the human sentence first, then `Used in:` and `Do not:`
// folded onto single lines so a token costs three comment lines, not nine.
export function docLines(docs, tokenPath) {
  const text = docs.get(tokenPath);
  if (!text) {
    return [];
  }
  return text
    .replace(/\nUsed in:\n/gu, '\nUsed in: ')
    .replace(/\nDo not:\n/gu, '\nDo not: ')
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean);
}

export const comment = (lines, prefix) => lines.map(line => `${prefix}${line}`).join('\n');

export const xmlDoc = (docs, tokenPath, indent) => docLines(docs, tokenPath).map(line => `${indent}<!-- ${line.replace(/--+/gu, '—')} -->`);

export const swiftDoc = (docs, tokenPath, indent) => docLines(docs, tokenPath).map(line => `${indent}/// ${line}`);
